import "./css/Festval_CardList.css";
import Festval_CardItem from "./Festval_CardItem.js";

import axios from "axios";
import { useEffect, useState } from "react";



const Festval_CardList = () =>{

    const [cardItems, setCardItems] = useState(null);
  
    useEffect(() => {
        const Loging = async() => { // async를 사용하는 함수 따로 선언

            const baseUrl = "http://apis.data.go.kr/B551011/KorService1/searchFestival1";
            //const serviceKey = "";
            const serviceKey = "Av0j4qFKXlogzFTNST8uPV8AmR6bdc5h9gNecQv1RR7v92yhfpCYFHj19OoN6mlq00fxLxYyEif4u5cu2GP%2BQA%3D%3D";
            const MobileOS = "ETC";
            const MobileApp = "Nado";
            const eventStartDate = "20241101";
            const type = "json";
            
            try{
              const response = await axios.get(baseUrl+"?serviceKey="+serviceKey+"&MobileOS="+MobileOS+"&MobileApp="+MobileApp+"&arrange=A&listYN=Y&eventStartDate=20241101&_type="+type);        
              setCardItems(response.data.items);
            }catch(e){      
              console.log(e);
            }
          };
          Loging();
    },[]);


    return (
        <div className='card_list'>
            {cardItems.map(cardItems => (
                <Festval_CardItem key={cardItems.title} setCardItems={cardItems} />
            )
        )}          
        </div>
    );
}
